package travelsync;
import java.util.*;
public class Main {
 static final Scanner in=new Scanner(System.in);
 static class User {int id; String username,role; User(int i,String u,String r){id=i;username=u;role=r;} boolean admin(){return "ADMIN".equals(role);}}
 public static void main(String[] args){
  try{DB.initialize(); while(true){System.out.println("\n=== TravelSync DSA3 ===\n1 Login\n2 Register User\n0 Exit");switch(num("Choose: ")){case 1->login();case 2->register();case 0->{return;}default->System.out.println("Invalid choice.");}}}
  catch(Exception e){System.out.println("Database/startup error: "+e.getMessage()+"\nCheck DB.java credentials, PostgreSQL service, database, and JDBC JAR.");}
 }
 static int num(String p){while(true){System.out.print(p);try{return Integer.parseInt(in.nextLine().trim());}catch(Exception e){System.out.println("Enter a number.");}}}
 static String ask(String p){System.out.print(p);return in.nextLine();}
 static void login(){try{String u=ask("Username: "),p=ask("Password: "),r=ask("Role (ADMIN/USER): ").trim().toUpperCase();User x=DB.login(u,p,r);if(x==null){System.out.println("Invalid username/password/role.");return;}System.out.println("Welcome "+x.username);if(x.admin())adminMenu();else userMenu();}catch(Exception e){System.out.println("Login error: "+e.getMessage());}}
 static void register(){String u=ask("Username (3-24 letters/numbers/_): ").trim(),p=ask("Password (8+ chars): ");if(!u.matches("[A-Za-z0-9_]{3,24}")||p.length()<8){System.out.println("Invalid username or password.");return;}try{DB.register(u,p);System.out.println("Registered as USER. You can log in now.");}catch(Exception e){System.out.println("Registration failed: "+e.getMessage());}}
 static void adminMenu()throws Exception{while(true){System.out.println("\n--- ADMIN DASHBOARD ---\n1 View destinations\n2 Search destinations (KMP)\n3 Add destination\n4 Update destination\n5 Delete destination\n6 List accounts\n7 DSA3 Algorithm Lab\n0 Logout");switch(num("Choose: ")){case 1->show(DB.destinations());case 2->search();case 3->save(0);case 4->save(num("ID to update: "));case 5->delete();case 6->{for(Object[] a:DB.users())System.out.println(Arrays.toString(a));}case 7->algorithms();case 0->{return;}default->System.out.println("Invalid.");}}}
 static void userMenu()throws Exception{while(true){System.out.println("\n--- USER DASHBOARD ---\n1 View destinations\n2 Search destinations (KMP)\n3 Fuzzy destination suggestion\n4 DSA3 Algorithm Lab\n0 Logout");switch(num("Choose: ")){case 1->show(DB.destinations());case 2->search();case 3->fuzzy();case 4->algorithms();case 0->{return;}default->System.out.println("Invalid.");}}}
 static void show(List<DB.Destination> ds){System.out.printf("%-4s %-20s %-24s %-28s %s%n","ID","Destination","Hotel","Attraction","KM");for(var d:ds)System.out.printf("%-4d %-20s %-24s %-28s %d%n",d.id,d.name,d.hotel,d.attraction,d.km);}
 static void search()throws Exception{String q=ask("Keyword: ").toLowerCase();List<DB.Destination> out=new ArrayList<>();for(var d:DB.destinations())if(Algorithms.kmpContains((d.name+" "+d.hotel+" "+d.attraction).toLowerCase(),q))out.add(d);show(out);}
 static void save(int id)throws Exception{DB.Destination old=id==0?null:DB.get(id);if(id!=0&&old==null){System.out.println("ID not found.");return;}String n=ask("Destination name"+(old==null?"":" ["+old.name+"]")+": ").trim(),h=ask("Hotel"+(old==null?"":" ["+old.hotel+"]")+": ").trim(),a=ask("Attraction"+(old==null?"":" ["+old.attraction+"]")+": ").trim();int km=num("Distance km"+(old==null?"":" ["+old.km+"]")+": ");if(old!=null){if(n.isEmpty())n=old.name;if(h.isEmpty())h=old.hotel;if(a.isEmpty())a=old.attraction;if(km==0)km=old.km;}if(n.isEmpty()||km<0){System.out.println("Name required; distance must be non-negative.");return;}DB.save(id,n,h,a,km);System.out.println("Saved.");}
 static void delete()throws Exception{int id=num("Destination ID: ");DB.Destination d=DB.get(id);if(d==null){System.out.println("Not found.");return;}if(ask("Delete "+d.name+"? (yes/no): ").equalsIgnoreCase("yes")){DB.delete(id);System.out.println("Deleted.");}}
 static void fuzzy()throws Exception{String q=ask("Destination spelling: ").toLowerCase(),best="";int score=Integer.MAX_VALUE;for(var d:DB.destinations()){int n=Algorithms.distance(q,d.name.toLowerCase());if(n<score){score=n;best=d.name;}}System.out.println("Closest: "+best+" (edit distance "+score+")");}
 static void algorithms()throws Exception{while(true){System.out.println("\n--- DSA3 LAB ---\n1 KMP\n2 Edit distance\n3 Dijkstra route demo\n4 Edmonds-Karp max-flow\n5 Bitmask TSP\n6 Randomized quicksort\n7 Reservoir sampling\n0 Back");switch(num("Choose: ")){case 1->System.out.println("Match indices: "+Algorithms.kmp(ask("Text: "),ask("Pattern: ")));case 2->System.out.println("Edit distance: "+Algorithms.distance(ask("First: "),ask("Second: ")));case 3->System.out.println(Algorithms.route());case 4->System.out.println("Max flow: "+Algorithms.flow());case 5->System.out.println(Algorithms.tsp());case 6->System.out.println(Algorithms.sortDemo());case 7->System.out.println(Algorithms.sample(Arrays.asList("BK1","BK2","BK3","BK4","BK5","BK6"),3));case 0->{return;}default->System.out.println("Invalid.");}}}
}
